            description: "\u0627\u0632 \u062F\u0627\u062F\u0647\u200C\u0647\u0627\u06CC \u0639\u0645\u0648\u0645\u06CC Return YouTube Dislike API (returnyoutubedislike.com) \u0628\u0631\u0627\u06CC \u0646\u0645\u0627\u06CC\u0634 \u062A\u0639\u062F\u0627\u062F \u062A\u0642\u0631\u06CC\u0628\u06CC \u062F\u06CC\u0633\u200C\u0644\u0627\u06CC\u06A9\u200C\u0647\u0627 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0645\u06CC\u200C\u06A9\u0646\u062F. \u0633\u0631\u0639\u062A \u0628\u0627\u0631\u06AF\u06CC\u0631\u06CC \u0648\u06CC\u062F\u06CC\u0648 \u0631\u0627 \u06A9\u0627\u0647\u0634 \u0645\u06CC\u200C\u062F\u0647\u062F \u0632\u06CC\u0631\u0627 \u0628\u0627\u06CC\u062F \u0627\u0637\u0644\u0627\u0639\u0627\u062A \u0631\u0627 \u0627\u0632 \u0633\u0631\u0648\u0631 \u062F\u0631\u06CC\u0627\u0641\u062A \u06A9\u0646\u062F"
