            notice_description: "\u0627\u06CC\u0646 \u0642\u0627\u0628\u0644\u06CC\u062A\u200C\u0647\u0627\u06CC \u0627\u062E\u062A\u06CC\u0627\u0631\u06CC\u060C VacuumTube \u0631\u0627 \u0641\u0631\u0627\u062A\u0631 \u0627\u0632 \u062A\u062C\u0631\u0628\u0647 \u0627\u0633\u062A\u0627\u0646\u062F\u0627\u0631\u062F YouTube \u062F\u0631 \u062A\u0644\u0648\u06CC\u0632\u06CC\u0648\u0646 \u06AF\u0633\u062A\u0631\u0634 \u0645\u06CC\u200C\u062F\u0647\u0646\u062F. \u0628\u0627 \u0641\u0639\u0627\u0644\u200C\u0633\u0627\u0632\u06CC \u0622\u0646\u200C\u0647\u0627 \u062F\u0631 \u0632\u06CC\u0631\u060C \u0645\u06CC\u200C\u067E\u0630\u06CC\u0631\u06CC\u062F \u06A9\u0647 \u0627\u06CC\u0646 \u0642\u0627\u0628\u0644\u06CC\u062A\u200C\u0647\u0627 \u0628\u0647 \u0631\u0641\u062A\u0627\u0631 \u062F\u0627\u062E\u0644\u06CC YouTube \u0648\u0627\u0628\u0633\u062A\u0647 \u0647\u0633\u062A\u0646\u062F \u0648 \u0645\u0645\u06A9\u0646 \u0627\u0633\u062A \u0628\u062F\u0648\u0646 \u0627\u0637\u0644\u0627\u0639 \u0642\u0628\u0644\u06CC \u062A\u063A\u06CC\u06CC\u0631 \u06A9\u0646\u0646\u062F \u06CC\u0627 \u0627\u0632 \u06A9\u0627\u0631 \u0628\u06CC\u0641\u062A\u0646\u062F.",
            enable_title: "\u0641\u0639\u0627\u0644\u200C\u0633\u0627\u0632\u06CC \u0642\u0627\u0628\u0644\u06CC\u062A\u200C\u0647\u0627\u06CC \u0627\u062E\u062A\u06CC\u0627\u0631\u06CC",
